use Aurelle\Services\Platform;
$tab=$data['tab'];
function dashboardHidden(string $action,int $id=0,string $tab='overview'): string { return csrf().'<input type="hidden" name="action" value="'.e($action).'"><input type="hidden" name="id" value="'.$id.'"><input type="hidden" name="tab" value="'.e($tab).'">'; }
$tabs=['overview'=>'Your overview','favorites'=>'Saved homes','collections'=>'Shared collections','searches'=>'Saved searches','listings'=>'Your properties','viewings'=>'Viewings & calendar','proposals'=>'Proposals & progress','messages'=>'Conversations','documents'=>'Private documents','services'=>'Services & invoices','notifications'=>'Notifications','settings'=>'Account & preferences'];
if (Auth::has('agent')) $tabs['crm']='Agent workspace';
?>
<div class="dashboard-layout"><aside class="dashboard-nav"><span class="eyebrow">MY VEYRA</span><?php foreach ($tabs as $key=>$label): ?><a class="<?= $tab===$key?'selected':'' ?>" href="/dashboard?tab=<?= $key ?>"><?= $label ?><?= $key==='messages' && array_sum(array_column($data['conversations'],'unread'))?' · '.array_sum(array_column($data['conversations'],'unread')):'' ?></a><?php endforeach ?><?php if (Auth::has('admin')): ?><a href="/admin">Administration <?= icon('arrow') ?></a><?php endif ?><form action="/logout" method="post"><?= csrf() ?><button class="plain">Sign out</button></form></aside><section class="dashboard-content"><div class="dashboard-title"><div><span class="eyebrow">YOUR NEXT CHAPTER</span><h1><?= e($tabs[$tab] ?? 'Your overview') ?></h1><p>Welcome, <?= e(explode(' ',$user['name'])[0]) ?>. All dates shown below are UTC unless labeled otherwise.</p></div><a class="button small" href="/properties">Explore the collection <?= icon('arrow') ?></a></div>
<?php if ($tab==='overview'): ?><div class="stats-grid"><?php foreach (['Saved homes'=>count($data['favorites']),'Your properties'=>count($data['listings']),'Viewings'=>count($data['viewings']),'Unread messages'=>array_sum(array_column($data['conversations'],'unread'))] as $label=>$n): ?><div class="stat"><span><?= $label ?></span><strong><?= $n ?></strong></div><?php endforeach ?></div><div class="two-column"><div class="panel"><h3>A few places to begin.</h3><p>Keep your favorite homes close, organize a shortlist with someone you trust, or introduce a property of your own.</p><div class="record-links"><a href="/dashboard?tab=collections">Your collections</a><a href="/submit">Submit a property</a></div></div><div class="panel"><h3>Your recent updates</h3><?php foreach (array_slice($data['notifications'],0,4) as $n): ?><p><a href="<?= e($n['link']) ?>"><?= e($n['title']) ?></a><br><span class="tiny"><?= e($n['created_at']) ?> UTC</span></p><?php endforeach; if (!$data['notifications']): ?><p>No new updates yet.</p><?php endif ?></div></div><h3>Saved for your next chapter</h3><br><div class="property-grid"><?php foreach (array_slice($data['favorites'],0,3) as $p) require ROOT.'/templates/partials/property-card.php'; ?></div>
<?php elseif ($tab==='favorites'): ?><div class="property-grid"><?php foreach ($data['favorites'] as $p) require ROOT.'/templates/partials/property-card.php'; ?></div><?php if (!$data['favorites']): ?><div class="empty"><h3>Your next chapter is waiting.</h3><p>Tap the heart on a home to keep it here.</p><a class="button" href="/properties">Find a home</a></div><?php endif ?>
<?php elseif ($tab==='collections'): ?><div class="panel"><h3>A shortlist to share.</h3><form class="form-row" method="post" action="/dashboard/action"><?= dashboardHidden('collection_create',0,$tab) ?><input class="input" name="name" required placeholder="Collection name"><button class="button">Create collection</button></form></div><?php foreach ($data['collections'] as $c): ?><article class="record"><div class="record-head"><h3><?= e($c['name']) ?></h3><span class="badge"><?= $c['owner_id']==$user['id']?'Owner':'Collaborator' ?></span></div><div class="form-row"><?php foreach (DB::all('SELECT u.id,u.name FROM collection_memberships cm JOIN users u ON u.id=cm.user_id WHERE cm.collection_id=?',[$c['id']]) as $member): ?><span class="tiny"><?= e($member['name']) ?></span><?php if ($c['owner_id']==$user['id'] && $member['id']!=$user['id']): ?><form action="/dashboard/action" method="post"><?= dashboardHidden('collection_remove',$c['id'],$tab) ?><input type="hidden" name="user_id" value="<?= $member['id'] ?>"><button class="plain">Remove</button></form><?php endif; endforeach ?></div><?php if ($c['owner_id']==$user['id']): ?><form class="form-row" method="post" action="/dashboard/action"><?= dashboardHidden('collection_invite',$c['id'],$tab) ?><input class="input" type="email" name="email" required placeholder="Invite a registered collaborator by email"><button class="button small">Invite</button></form><?php endif ?><form class="form-row" method="post" action="/dashboard/action"><?= dashboardHidden('collection_add',$c['id'],$tab) ?><input class="input" type="number" name="listing_id" min="1" placeholder="Property ID from its URL" required><button class="button small">Add home</button></form><div class="property-grid"><?php foreach (DB::all('SELECT l.* FROM collection_listings cl JOIN listings l ON l.id=cl.listing_id WHERE cl.collection_id=? AND l.status IN ("published","under_offer")',[$c['id']]) as $p): require ROOT.'/templates/partials/property-card.php'; endforeach ?></div><form class="form-row" method="post" action="/dashboard/action"><?= dashboardHidden('collection_comment',$c['id'],$tab) ?><input class="input" name="listing_id" type="number" placeholder="Property ID" min="1" required><input class="input" name="body" required placeholder="Share a thought about this home"><button class="button small">Comment</button></form><?php foreach (DB::all('SELECT cc.*,u.name FROM collection_comments cc JOIN users u ON u.id=cc.user_id WHERE cc.collection_id=? ORDER BY cc.id DESC LIMIT 30',[$c['id']]) as $comment): ?><p><b><?= e($comment['name']) ?></b> · Home #<?= $comment['listing_id'] ?><br><?= e($comment['body']) ?></p><?php endforeach ?><form action="/dashboard/action" method="post"><?= dashboardHidden('collection_chat',$c['id'],'messages') ?><button class="button outline small">Open group conversation</button></form></article><?php endforeach ?>
<?php elseif ($tab==='searches'): ?><?php foreach ($data['searches'] as $s): ?><div class="record"><div class="record-head"><h3><?= e($s['name']) ?></h3><a class="text-link" href="/properties?<?= e(http_build_query(json_decode($s['filters'],true))) ?>">Run search <?= icon('arrow') ?></a></div><p class="tiny">New matching properties generate in-app alerts when the alert worker runs. Email and SMS are disabled.</p><form action="/dashboard/action" method="post"><?= dashboardHidden('search_delete',$s['id'],$tab) ?><button class="plain">Remove search</button></form></div><?php endforeach; if (!$data['searches']): ?><div class="empty">Save a search from the property search page.</div><?php endif ?>
<?php elseif ($tab==='listings'): ?><a class="button" href="/submit">Introduce a property <?= icon('arrow') ?></a><br><br><?php foreach ($data['listings'] as $p): ?><article class="record"><div class="record-head"><h3><?= e($p['title']) ?></h3><span class="badge <?= e($p['status']) ?>"><?= e(str_replace('_',' ',$p['status'])) ?></span></div><p><?= money($p['price_minor']) ?> · <?= e($p['city']) ?> · Assigned agent: <?= e(DB::one('SELECT name FROM users WHERE id=?',[$p['agent_id']])['name'] ?? 'Awaiting assignment') ?></p><p class="tiny"><?= $p['views'] ?> detail-page loads · <?= $p['favorites_count'] ?> current saves · <?= $p['inquiries'] ?> conversation openings. Counts include demonstration activity and are not unique visitors.</p><div class="record-links"><a href="/submit?id=<?= $p['id'] ?>">Edit property</a><a href="/property?id=<?= $p['id'] ?>">View property</a><?php if ($p['agent_id'] && $p['agent_id']!=$user['id']): ?><form action="/conversation" method="post"><?= csrf() ?><input type="hidden" name="id" value="<?= $p['id'] ?>"><button class="plain">Message assigned agent</button></form><?php endif ?></div><form class="form-row" method="post" action="/dashboard/action"><?= dashboardHidden('listing_state',$p['id'],$tab) ?><select class="input" name="state"><option value="submitted">Submit for review</option><option value="withdrawn">Withdraw</option><option value="under_offer">Mark under offer</option><option value="draft">Return to draft</option></select><button class="button small">Update status</button></form><details><summary>Review and status history</summary><div class="history"><?php foreach (DB::all('SELECT * FROM listing_status_history WHERE listing_id=? ORDER BY id DESC',[$p['id']]) as $h): ?><div><?= e($h['created_at']) ?> · <?= e($h['from_status']) ?> → <?= e($h['to_status']) ?> · <?= e($h['reason']) ?></div><?php endforeach ?></div></details><details><summary>Manage viewing availability</summary><form method="post" action="/dashboard/action"><?= dashboardHidden('availability',$p['id'],$tab) ?><div class="form-grid"><label class="field"><span>Start</span><input type="datetime-local" name="starts_at" required></label><label class="field"><span>End</span><input type="datetime-local" name="ends_at" required></label><label class="field"><span>Time zone</span><input name="timezone" value="<?= e($user['timezone']) ?>" required data-timezone></label><label><input type="checkbox" name="open_house"> Open house</label></div><button class="button small">Add availability</button></form></details><details><summary>Cover photograph</summary><?php foreach (DB::all('SELECT * FROM listing_media WHERE listing_id=? AND kind="photo" ORDER BY sort_order',[$p['id']]) as $media): ?><form class="form-row" action="/dashboard/action" method="post"><?= dashboardHidden('media_cover',$media['id'],$tab) ?><span class="tiny">Photo #<?= $media['id'] ?> · order <?= $media['sort_order'] ?></span><button class="plain">Make cover</button></form><?php endforeach ?></details></article><?php endforeach ?><h3>Valuation requests</h3><?php foreach ($data['valuations'] as $v): ?><div class="record"><b><?= e($v['address']) ?></b><p><?= e($v['details']) ?></p><span class="badge"><?= e($v['status']) ?></span></div><?php endforeach ?>
<?php elseif ($tab==='viewings'): require ROOT.'/templates/partials/calendar.php'; ?><?php foreach ($data['viewings'] as $v): ?><article class="record" id="viewing-<?= $v['id'] ?>"><div class="record-head"><h3><?= e($v['title']) ?></h3><span class="badge <?= e($v['status']) ?>"><?= e(str_replace('_',' ',$v['status'])) ?></span></div><p><?= e($v['starts_at']) ?> – <?= e($v['ends_at']) ?> UTC<br><span class="tiny">Requested in <?= e($v['timezone']) ?> · <?= e($v['note']) ?></span></p><form class="form-row" method="post" action="/dashboard/action"><?= dashboardHidden('viewing_state',$v['id'],$tab) ?><select class="input" name="state"><option value="cancelled">Cancel</option><?php if ($v['agent_id']==$user['id']): ?><option value="confirmed">Confirm</option><option value="completed">Completed</option><option value="no_show">No-show</option><?php endif ?></select><button class="button small">Update appointment</button></form><?php if ($v['status']==='completed' && $v['customer_id']==$user['id'] && !DB::one('SELECT id FROM reviews WHERE viewing_id=?',[$v['id']])): ?><details><summary>Review your eligible interaction</summary><form class="form-row" action="/dashboard/action" method="post"><?= dashboardHidden('review',$v['id'],$tab) ?><select class="input" name="rating"><option value="5">5 / 5</option><option value="4">4 / 5</option><option value="3">3 / 5</option><option value="2">2 / 5</option><option value="1">1 / 5</option></select><input class="input" name="body" required placeholder="Your experience"><button class="button small">Submit for moderation</button></form></details><?php endif ?></article><?php endforeach; if (!$data['viewings']): ?><div class="empty"><h3>A closer look begins here.</h3><p>Request an appointment from a property page.</p></div><?php endif ?>
<?php elseif ($tab==='proposals'): ?><div class="notice">Acceptance records agreement in principle. It does not complete a transaction or transfer legal ownership.</div><?php foreach ($data['proposals'] as $p): ?><article class="record"><div class="record-head"><h3><?= e($p['title']) ?></h3><span class="badge"><?= e($p['status']) ?></span></div><?php foreach (DB::all('SELECT r.*,u.name FROM proposal_revisions r JOIN users u ON u.id=r.actor_id WHERE r.proposal_id=? ORDER BY r.id',[$p['id']]) as $r): ?><div class="history"><b><?= money($r['amount_minor']) ?></b> · <?= e($r['name']) ?> · <?= e($r['created_at']) ?><p><?= nl2br(e($r['terms'])) ?></p></div><?php endforeach ?><form method="post" action="/dashboard/action"><?= dashboardHidden('proposal_state',$p['id'],$tab) ?><div class="form-row"><select class="input" name="state"><option value="acknowledged">Acknowledge</option><option value="countered">Counter proposal</option><option value="accepted">Accept in principle</option><option value="rejected">Reject</option><option value="withdrawn">Withdraw</option></select><input class="input" type="number" name="amount" min="1" step=".01" placeholder="Counter amount ($)"></div><label class="field"><span>Counter terms (only for a counter proposal)</span><textarea name="terms"></textarea></label><button class="button small">Record response</button></form><?php $checklist=DB::all('SELECT * FROM transaction_checklists WHERE proposal_id=?',[$p['id']]); if ($checklist): ?><h3>Transaction progress</h3><?php foreach ($checklist as $item): ?><form class="form-row" method="post" action="/dashboard/action"><?= dashboardHidden('checklist',$item['id'],$tab) ?><button class="plain"><?= $item['completed_at']?'☑':'☐' ?> <?= e($item['title']) ?></button><span class="tiny"><?= e($item['completed_at']) ?></span></form><?php endforeach ?><form class="form-row" action="/dashboard/action" method="post"><?= dashboardHidden('checklist_add',$p['id'],$tab) ?><input class="input" name="title" required placeholder="Add a transaction milestone"><button class="button small">Add milestone</button></form><?php endif ?><details><summary>Dated status history</summary><div class="history"><?php foreach (DB::all('SELECT * FROM workflow_history WHERE entity_type="proposal" AND entity_id=? ORDER BY id',[$p['id']]) as $h): ?><div><?= e($h['created_at']) ?> · <?= e($h['state']) ?></div><?php endforeach ?></div></details></article><?php endforeach; if (!$data['proposals']): ?><div class="empty">Your submitted proposals and rental inquiries will appear here.</div><?php endif ?>
<?php elseif ($tab==='messages'): ?><?php $cid=(int)($_GET['conversation'] ?? ($data['conversations'][0]['id'] ?? 0)); $conversation=$cid?Messaging::access($user['id'],$cid):null; ?><div class="chat-layout"><nav class="chat-threads" aria-label="Conversations"><?php foreach ($data['conversations'] as $c): ?><a class="<?= $cid===$c['id']?'selected':'' ?>" href="/dashboard?tab=messages&conversation=<?= $c['id'] ?>"><?= e($c['title']) ?><b><?= $c['unread'] ?> unread</b></a><?php endforeach ?></nav><div class="chat-main" <?= $cid?'data-chat="'.$cid.'"':'' ?>><div class="chat-header"><span><?= e($conversation['title'] ?? 'Your conversations') ?></span><span class="chat-transport" data-transport>Connecting…</span></div><?php if ($cid): ?><div class="form-row"><input class="input" data-message-search placeholder="Search this conversation" aria-label="Search conversation"><button class="plain" data-chat-search>Search</button><button class="plain" data-chat-recent>Recent</button></div><button class="plain" data-chat-older>Load earlier messages</button><div class="chat-messages" aria-live="polite" aria-label="Messages"></div><div class="chat-typing" data-typing></div><div class="chat-error" role="status"></div><form class="chat-compose"><textarea name="body" required maxlength="10000" rows="2" aria-label="Your message" placeholder="Write a thoughtful note…"></textarea><button class="button">Send <?= icon('arrow') ?></button></form><?php else: ?><div class="empty"><h3>A conversation starts with a home.</h3><p>Message an assigned agent from any property page.</p></div><?php endif ?></div></div><p class="tiny">Delivered means fetched by a recipient’s session. Read means displayed in a visible conversation. Presence is opt-in. If the worker is unavailable, messages use near-real-time polling every 5 seconds.</p><?php if ($cid): ?><details class="panel"><summary>Attachments, safety & privacy</summary><p class="tiny">Upload attachments against a message you sent. Participant access is checked on each download.</p><?php $attachments=DB::all('SELECT d.* FROM documents d JOIN messages m ON m.id=d.message_id WHERE m.conversation_id=? ORDER BY d.id DESC',[$cid]); foreach ($attachments as $d): ?><p><a class="text-link" href="/download?id=<?= $d['id'] ?>"><?= e($d['original_name']) ?> <?= icon('arrow') ?></a></p><?php endforeach ?><form class="form-row" action="/dashboard/action" method="post" enctype="multipart/form-data"><?= dashboardHidden('attachment',0,$tab) ?><input class="input" name="id" type="number" required placeholder="Your sent message ID"><input class="input" type="file" name="file" required accept="image/jpeg,image/png,image/webp,application/pdf"><button class="button small">Upload attachment</button></form><form class="form-row" action="/dashboard/action" method="post"><?= dashboardHidden('report',$cid,$tab) ?><input class="input" name="reason" required placeholder="Report reason"><button class="button small">Report conversation</button></form><form class="form-row" action="/dashboard/action" method="post"><?= dashboardHidden('block',$cid,$tab) ?><select class="input" name="user_id"><?php foreach (DB::all('SELECT u.id,u.name FROM users u JOIN conversation_participants cp ON cp.user_id=u.id WHERE cp.conversation_id=? AND u.id<>?',[$cid,$user['id']]) as $participant): ?><option value="<?= $participant['id'] ?>"><?= e($participant['name']) ?></option><?php endforeach ?></select><button class="button small outline">Block messages</button></form></details><?php endif ?><form action="/dashboard/action" method="post"><?= dashboardHidden('support',0,$tab) ?><button class="button outline small">Start a support conversation</button></form>
<?php elseif ($tab==='documents'): ?><div class="panel"><h3>Your documents, kept private.</h3><form class="form-row" method="post" action="/dashboard/action" enctype="multipart/form-data"><?= dashboardHidden('document_upload',0,$tab) ?><input class="input" type="file" name="file" required accept="application/pdf,image/jpeg,image/png,image/webp"><button class="button">Upload document</button></form><p class="tiny">PDF or image, up to 8 MB. Downloads require ownership or an explicit share; administrators have no general document access.</p></div><?php foreach ($data['documents'] as $d): ?><div class="record"><div class="record-head"><h3><?= e($d['original_name']) ?></h3><a class="text-link" href="/download?id=<?= $d['id'] ?>">Download <?= icon('arrow') ?></a></div><p class="tiny"><?= number_format($d['size_bytes']/1024) ?> KB · <?= e($d['created_at']) ?> UTC</p><?php if ($d['owner_id']==$user['id']): ?><form class="form-row" method="post" action="/dashboard/action"><?= dashboardHidden('document_share',$d['id'],$tab) ?><input class="input" name="email" type="email" required placeholder="Share with a registered user"><button class="button small">Share privately</button></form><?php foreach (DB::all('SELECT s.user_id,u.name FROM document_shares s JOIN users u ON u.id=s.user_id WHERE document_id=?',[$d['id']]) as $share): ?><form class="form-row" action="/dashboard/action" method="post"><?= dashboardHidden('document_revoke',$d['id'],$tab) ?><input type="hidden" name="user_id" value="<?= $share['user_id'] ?>"><span class="tiny">Shared with <?= e($share['name']) ?></span><button class="plain">Revoke</button></form><?php endforeach; endif ?></div><?php endforeach ?>
<?php elseif ($tab==='crm' && Auth::has('agent')): ?><div class="notice">CRM notes are internal to the assigned agent. They are never included in customer conversations.</div><?php foreach ($data['leads'] as $lead): ?><div class="record"><div class="record-head"><h3><?= e($lead['name']) ?></h3><span class="badge"><?= e($lead['stage']) ?></span></div><p><?= e($lead['email']) ?> · <?= e($lead['title']) ?></p><form action="/dashboard/action" method="post"><?= dashboardHidden('lead_update',$lead['id'],$tab) ?><div class="form-row"><select class="input" name="stage"><?php foreach (['new','contacted','qualified','viewing','proposal','closed','lost'] as $stage): ?><option <?= $lead['stage']===$stage?'selected':'' ?>><?= $stage ?></option><?php endforeach ?></select><input class="input" name="note" placeholder="Add an internal note"><button class="button small">Update pipeline</button></div></form><?php foreach (DB::all('SELECT * FROM lead_notes WHERE lead_id=? ORDER BY id DESC',[$lead['id']]) as $note): ?><p class="tiny"><?= e($note['body']) ?> · <?= e($note['created_at']) ?></p><?php endforeach ?></div><?php endforeach ?><div class="panel"><h3>Tasks & follow-ups</h3><form class="form-row" action="/dashboard/action" method="post"><?= dashboardHidden('task_create',0,$tab) ?><input class="input" name="title" required placeholder="Follow-up task"><input class="input" name="due_at" type="datetime-local" required aria-label="Due date in UTC"><button class="button small">Add task</button></form><?php foreach ($data['tasks'] as $task): ?><form class="form-row" method="post" action="/dashboard/action"><?= dashboardHidden('task_complete',$task['id'],$tab) ?><span><?= e($task['title']) ?> · <?= e($task['due_at']) ?> UTC</span><button class="plain"><?= $task['completed_at']?'Completed':'Mark complete' ?></button></form><?php endforeach ?></div>
<?php elseif ($tab==='services'): ?><div class="notice">Service charges are separate from property prices. Online payment collection is disabled; manual records do not claim a provider charge was made.</div><a class="button small" href="/services">Explore property services</a><br><br><?php foreach ($data['requests'] as $r): ?><div class="record"><div class="record-head"><h3><?= e($r['name']) ?></h3><span class="badge"><?= e($r['status']) ?></span></div><p><?= e($r['details']) ?></p><?php if ($r['quote_minor']): ?><p>Quote: <?= money($r['quote_minor']) ?></p><?php endif; if ($r['appointment_at']): ?><p>Appointment: <?= e($r['appointment_at']) ?> UTC</p><?php endif ?></div><?php endforeach ?><h3>Service invoices</h3><br><?php foreach ($data['invoices'] as $i): ?><div class="record"><div class="record-head"><h3>Invoice #<?= $i['id'] ?></h3><span class="badge"><?= e($i['status']) ?></span></div><p>Total: <?= money($i['total_minor']) ?> USD</p><?php foreach (DB::all('SELECT * FROM payments WHERE invoice_id=?',[$i['id']]) as $pay): ?><p class="tiny">Manual payment record #<?= $pay['id'] ?>: <?= money($pay['amount_minor']) ?> · <?= e($pay['reference']) ?> · <?= e($pay['created_at']) ?></p><?php foreach (DB::all('SELECT * FROM refunds WHERE payment_id=?',[$pay['id']]) as $refund): ?><p class="tiny">Refund record: <?= money($refund['amount_minor']) ?> · <?= e($refund['reason']) ?></p><?php endforeach; endforeach ?></div><?php endforeach ?>
<?php elseif ($tab==='notifications'): ?><form action="/dashboard/action" method="post"><?= dashboardHidden('notification_read',0,$tab) ?><button class="button small">Mark all as read</button></form><br><?php foreach ($data['notifications'] as $n): ?><a class="record" href="<?= e($n['link']) ?>"><b><?= e($n['title']) ?><?= $n['read_at']?'':' · Unread' ?></b><p><?= e($n['body']) ?></p><span class="tiny"><?= e($n['created_at']) ?> UTC · In-app notification</span></a><?php endforeach ?>
<?php elseif ($tab==='settings'): ?><div class="panel"><h3>Make Veyra work for you.</h3><form method="post" action="/dashboard/action"><?= dashboardHidden('settings',0,$tab) ?><label class="field"><span>Time zone (IANA name)</span><input name="timezone" value="<?= e($user['timezone']) ?>" required></label><div class="check-list"><label><input type="checkbox" name="show_presence" <?= $user['show_presence']?'checked':'' ?>> Share presence with conversation participants</label><label><input type="checkbox" name="in_app" <?= (json_decode($user['notification_preferences'] ?? '{}',true)['in_app'] ?? true)?'checked':'' ?>> In-app notifications</label></div><p class="tiny">Email and SMS integrations are disabled. No delivery claims are made.</p><button class="button">Save preferences</button></form></div><div class="panel"><h3>Become an Veyra agent.</h3><?php if ($data['application']): ?><p>Application status: <?= $data['application']['approved_at']?'Approved':'Awaiting administrator review' ?>. Verification: <?= $data['application']['verified_at']?'Reviewed':'Not verified' ?>.</p><?php else: ?><p>Agent access and verification require separate administrator actions.</p><form method="post" action="/dashboard/action"><?= dashboardHidden('agent_apply',0,$tab) ?><div class="form-grid"><?php foreach (['agency'=>'Agency','service_areas'=>'Service areas','languages'=>'Languages','specialties'=>'Specialties'] as $key=>$label): ?><label class="field"><span><?= $label ?></span><input name="<?= $key ?>" required></label><?php endforeach ?><label class="field wide"><span>Biography</span><textarea name="biography" required minlength="20"></textarea></label><label class="field wide"><span>Credentials for administrator review</span><textarea name="credentials" required minlength="5"></textarea></label></div><button class="button">Submit application</button></form><?php endif ?></div>
<?php else: ?><div class="empty">Choose a workspace from the navigation.</div><?php endif; require ROOT.'/templates/partials/dashboard-operations.php'; ?></section></div>
